 [string]$BindingPath
)
$ErrorActionPreference='Stop'

function Write-CanonicalJson([object]$Value,[string]$Path){$json=($Value|ConvertTo-Json -Depth 16)-replace"`r`n","`n";[IO.File]::WriteAllText($Path,$json+"`n",[Text.UTF8Encoding]::new($false))}
function Sha([string]$Path){(Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash}
function Hex64($Value){[string]$Value-match'^[0-9A-Fa-f]{64}$'}
function NonZeroAddress($Value){$text=[string]$Value;return($text-match'^0x[0-9A-Fa-f]{8,16}$'-and$text-notmatch'^0x0+$')}
function ExactKeys($Value,[string[]]$Expected){if($null-eq$Value){return$false};$a=@($Value.PSObject.Properties.Name|Sort-Object);$e=@($Expected|Sort-Object);return($a.Count-eq$e.Count-and(Compare-Object $e $a).Count-eq0)}
$blockers=[Collections.Generic.List[string]]::new();function Block([string]$Code){if(-not$blockers.Contains($Code)){$blockers.Add($Code)}}

try{$r=Get-Content -LiteralPath $ReceiptPath -Raw -Encoding UTF8|ConvertFrom-Json}catch{$r=$null;Block 'RECEIPT_JSON_INVALID'}
$client=$null;$debugger=$null;$agent=$null
if($null-ne$r){
 $root=@('schemaVersion','runId','provenance','observedAtUtc','helper','activeConsoleSessionId','absoluteProgram','processes','operations')
 if(-not(ExactKeys $r $root)){Block 'SCHEMA_ROOT_KEYS_MISMATCH'}
 if([int]$r.schemaVersion-ne1){Block 'SCHEMA_VERSION_UNSUPPORTED'}
 if([string]$r.runId-cne$RunId){Block 'RECEIPT_RUN_ID_MISMATCH'}
 if($r.provenance-notin@('SYNTHETIC_FIXTURE','LIVE_READONLY_CORRECTED_ROUTE_PREFLIGHT')){Block 'PROVENANCE_INVALID'}
 try{$observed=[datetime]$r.observedAtUtc}catch{$observed=[datetime]::MinValue;Block 'OBSERVED_TIME_INVALID'}
 if(-not(ExactKeys $r.helper @('pid','sessionId','userName','userSid'))){Block 'SCHEMA_HELPER_KEYS_MISMATCH'}
 if(-not(ExactKeys $r.absoluteProgram @('path','exists','sha256','length','observedAtUtc'))){Block 'SCHEMA_PROGRAM_KEYS_MISMATCH'}
 if([string]::IsNullOrWhiteSpace([string]$r.helper.userName)-or[string]$r.helper.userSid-notmatch'^S-\d-\d+(-\d+)+$'){Block 'OWNER_IDENTITY_INVALID'}
 if([int]$r.helper.sessionId-ne0){Block 'PREFLIGHT_HELPER_SESSION_NOT_0'}
 if([int]$r.activeConsoleSessionId-ne1){Block 'ACTIVE_CONSOLE_INVALID'}
 $expectedProgram='C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe'
 if([string]$r.absoluteProgram.path-cne$expectedProgram){Block 'ABSOLUTE_PROGRAM_PATH_MISMATCH'}
 if($r.absoluteProgram.exists-ne$true){Block 'ABSOLUTE_PROGRAM_MISSING'}
 if(-not(Hex64 $r.absoluteProgram.sha256)-or[int64]$r.absoluteProgram.length-le0){Block 'ABSOLUTE_PROGRAM_IDENTITY_INVALID'}
 try{$programObserved=[datetime]$r.absoluteProgram.observedAtUtc}catch{$programObserved=[datetime]::MinValue;Block 'ABSOLUTE_PROGRAM_IDENTITY_INVALID'}
 if($observed-ne[datetime]::MinValue-and(($EvaluationTimeUtc.ToUniversalTime()-$observed.ToUniversalTime()).TotalSeconds-gt120-or$observed.ToUniversalTime()-gt$EvaluationTimeUtc.ToUniversalTime())){Block 'PREFLIGHT_STALE'}
 if($programObserved-ne[datetime]::MinValue-and(($EvaluationTimeUtc.ToUniversalTime()-$programObserved.ToUniversalTime()).TotalSeconds-gt120-or$programObserved.ToUniversalTime()-gt$EvaluationTimeUtc.ToUniversalTime())){Block 'PREFLIGHT_STALE'}
 $processKeys=@('role','name','pid','sessionId','startTimeUtc','path','sha256','owner','ownerSid','ownerLookupStatus','moduleBase','moduleSize')
 $p=@($r.processes);foreach($process in $p){if(-not(ExactKeys $process $processKeys)){Block 'SCHEMA_PROCESS_KEYS_MISMATCH'}};$cs=@($p|Where-Object{$_.role-eq'CLIENT'});$ds=@($p|Where-Object{$_.role-eq'DEBUGGER'});$as=@($p|Where-Object{$_.role-eq'INTERACTIVE_AGENT'})
 if($cs.Count-ne1){Block 'CLIENT_COUNT_NOT_1'}else{$client=$cs[0]}
 if($ds.Count-ne1){Block 'DEBUGGER_COUNT_NOT_1'}else{$debugger=$ds[0]}
 if($as.Count-ne1){Block 'INTERACTIVE_AGENT_COUNT_NOT_1'}else{$agent=$as[0]}
 $positivePids=@($p|Where-Object{[int]$_.pid-gt0}|ForEach-Object{[int]$_.pid});if(($positivePids|Sort-Object -Unique).Count-ne$positivePids.Count){Block 'PROCESS_PID_COLLISION'}
 $active=[int]$r.activeConsoleSessionId;$ownerName=[string]$r.helper.userName;$ownerSid=[string]$r.helper.userSid
 if($client){if([int]$client.pid-le0){Block 'CLIENT_IDENTITY_INVALID'};if([string]$client.name-cne'G7MTClient'){Block 'CLIENT_NAME_MISMATCH'};if([string]$client.path-cne'C:\LOGH7_ORACLE\exe\G7MTClient.exe'){Block 'CLIENT_PATH_MISMATCH'};if([string]$client.sha256-cne'BD19263C10DECC3D58373165A82D42A9267868400D407DA87D5F4F4109AB6E16'){Block 'CLIENT_HASH_MISMATCH'};if([int]$client.sessionId-ne$active){Block 'CLIENT_SESSION_MISMATCH'};if([string]$client.ownerLookupStatus-cne'SUCCESS'){Block 'CLIENT_OWNER_LOOKUP_FAILED'};if([string]$client.owner-cne$ownerName){Block 'CLIENT_OWNER_MISMATCH'};if([string]$client.ownerSid-cne$ownerSid){Block 'CLIENT_OWNER_SID_MISMATCH'};if([int64]$client.moduleSize-le0-or-not(NonZeroAddress $client.moduleBase)){Block 'CLIENT_MODULE_IDENTITY_INVALID'};try{$clientStart=[datetime]$client.startTimeUtc;if($clientStart.ToUniversalTime()-gt$observed.ToUniversalTime()){throw'future'}}catch{Block 'CLIENT_START_TIME_INVALID'}}
 if($debugger){if([int]$debugger.pid-le0){Block 'DEBUGGER_IDENTITY_INVALID'};if([string]$debugger.name-cne'x32dbg'){Block 'DEBUGGER_NAME_MISMATCH'};if([string]$debugger.path-cne'C:\LOGH7_TOOLS\x64dbg-xp-2020-12-14\release\x32\x32dbg.exe'){Block 'DEBUGGER_PATH_MISMATCH'};if([string]$debugger.sha256-cne'42CF419B3549332AF44A8500E99085A0C590547CAE6950623FE592EA885711C6'){Block 'DEBUGGER_HASH_MISMATCH'};if([int]$debugger.sessionId-ne$active){Block 'DEBUGGER_SESSION_MISMATCH'};if([string]$debugger.ownerLookupStatus-cne'SUCCESS'){Block 'DEBUGGER_OWNER_LOOKUP_FAILED'};if([string]$debugger.owner-cne$ownerName){Block 'DEBUGGER_OWNER_MISMATCH'};if([string]$debugger.ownerSid-cne$ownerSid){Block 'DEBUGGER_OWNER_SID_MISMATCH'};if([int64]$debugger.moduleSize-le0-or-not(NonZeroAddress $debugger.moduleBase)){Block 'DEBUGGER_MODULE_IDENTITY_INVALID'};try{$debuggerStart=[datetime]$debugger.startTimeUtc;if($debuggerStart.ToUniversalTime()-gt$observed.ToUniversalTime()){throw'future'}}catch{Block 'DEBUGGER_START_TIME_INVALID'}}
 if($agent){if([int]$agent.pid-le0){Block 'INTERACTIVE_AGENT_IDENTITY_INVALID'};if([string]$agent.name-cne'vmtoolsd'){Block 'INTERACTIVE_AGENT_NAME_MISMATCH'};if([string]$agent.path-cne'C:\Program Files\VMware\VMware Tools\vmtoolsd.exe'){Block 'INTERACTIVE_AGENT_PATH_MISMATCH'};if([int]$agent.sessionId-ne$active){Block 'INTERACTIVE_AGENT_SESSION_MISMATCH'};if([string]$agent.ownerLookupStatus-cne'SUCCESS'){Block 'INTERACTIVE_AGENT_OWNER_LOOKUP_FAILED'};if([string]$agent.owner-cne$ownerName){Block 'INTERACTIVE_AGENT_OWNER_MISMATCH'};if([string]$agent.ownerSid-cne$ownerSid){Block 'INTERACTIVE_AGENT_OWNER_SID_MISMATCH'};if(-not(Hex64 $agent.sha256)){Block 'INTERACTIVE_AGENT_HASH_INVALID'};if([int64]$agent.moduleSize-le0-or-not(NonZeroAddress $agent.moduleBase)){Block 'INTERACTIVE_AGENT_MODULE_IDENTITY_INVALID'};try{$agentStart=[datetime]$agent.startTimeUtc;if($agentStart.ToUniversalTime()-gt$observed.ToUniversalTime()){throw'future'}}catch{Block 'INTERACTIVE_AGENT_START_TIME_INVALID'}}
